package app

import (
	"sync"

	"fyne.io/fyne/v2"
)

var (
	metaMutex sync.RWMutex
	appMeta   = fyne.AppMetadata{
		ID:      "com.example",
		Name:    "Fyne App",
		Version: "1.0.0",
		Build:   1,
	}
)

// SetMetadata sets the application metadata that will be returned by App.Metadata().
// This should be called before creating windows or running the app.
//
// Since: 2.5
func SetMetadata(meta fyne.AppMetadata) {
	metaMutex.Lock()
	appMeta = meta
	metaMutex.Unlock()
}

func (a *fyneApp) Metadata() fyne.AppMetadata {
	metaMutex.RLock()
	defer metaMutex.RUnlock()
	return appMeta
}

