package desktop

import "fyne.io/fyne/v2"

// App interface extends the standard fyne.App interface to add desktop-specific features.
//
// Since: 2.5
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the system tray menu for the application.
	// The menu will be displayed when the user interacts with the system tray icon.
	// Pass nil to remove the system tray menu.
	SetSystemTrayMenu(menu *fyne.Menu)
}

package validation

import (
	"fmt"
	"strings"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that requires all provided validators to pass.
// The validator will return nil if all validators pass, otherwise returns an error
// combining all validation failures.
//
// Since: 2.5
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		var errors []string

		for _, validator := range validators {
			if validator == nil {
				continue
			}

			err := validator(text)
			if err != nil {
				errors = append(errors, err.Error())
			}
		}

		if len(errors) == 0 {
			return nil
		}

		if len(errors) == 1 {
			return fmt.Errorf("%s", errors[0])
		}

		return fmt.Errorf("%s", strings.Join(errors, "; "))
	}
}

